package com.lifeblackbox.recorder;
import android.content.Context;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=29)
public class ReportStoreTest {
 Context c;String scope;final String day="2026-10-30";
 @Before public void setup()throws Exception {c=RuntimeEnvironment.getApplication();DriveBackup.prefs(c).edit().clear().commit();scope=ReportStore.scope(c);}
 JSONObject report()throws Exception {return new JSONObject().put("summary",new JSONArray().put("사용자가 가져온 핵심 요약")).put("sections",new JSONArray().put(new JSONObject().put("topic","speech").put("text","<script>untrusted</script>"))).put("todos",new JSONArray().put(new JSONObject().put("title","자료 확인").put("assignee","확인 필요").put("due",""))).put("speakers",new JSONArray().put(new JSONObject().put("label","A").put("name","추정 이름"))).put("priorities",new JSONArray().put("todo").put("speech")).put("extra","").put("length","core").put("coverage","사용자 제공");}
 JSONObject review(String person)throws Exception {JSONArray links=new JSONArray();if(person!=null)links.put(new JSONObject().put("index",0).put("personId",person));return new JSONObject().put("todos",new JSONArray().put(new JSONObject().put("index",0).put("title","수정한 할 일").put("assignee","나").put("due","2026-11-02").put("selected",true))).put("links",links);}
 @Test public void versionsKeepOriginalAndUserReviewWithoutInventingCompletion()throws Exception {JSONObject a=ReportStore.save(c,scope,day,report());ReportStore.review(c,scope,day,a.getString("id"),review(null));JSONObject b=ReportStore.save(c,scope,day,report().put("summary",new JSONArray().put("재분석 결과")));assertNotEquals(a.getString("id"),b.getString("id"));JSONObject first=ReportStore.load(c,scope,day,a.getString("id"));assertEquals(2,first.getJSONArray("versions").length());assertEquals("사용자가 가져온 핵심 요약",first.getJSONObject("report").getJSONArray("summary").getString(0));JSONObject task=first.getJSONObject("review").getJSONArray("todos").getJSONObject(0);assertTrue(task.getBoolean("selected"));assertFalse(task.has("completed"));assertFalse(task.has("registered"));assertEquals("수정한 할 일",task.getString("title"));assertEquals(0,ReportStore.load(c,scope,day,b.getString("id")).getJSONObject("review").optJSONArray("todos")==null?0:1);}
 @Test public void accountNamespacesAndStaleCallsNeverCrossAccounts()throws Exception {ReportStore.save(c,scope,day,report());DriveBackup.prefs(c).edit().putBoolean("enabled",true).putString("account","one").commit();String one=ReportStore.scope(c);assertNotEquals(scope,one);assertEquals(0,ReportStore.load(c,one,day,"").getJSONArray("versions").length());try{ReportStore.save(c,scope,day,report());fail();}catch(java.io.IOException expected){}ReportStore.save(c,one,day,report());DriveBackup.prefs(c).edit().putString("account","two").commit();String two=ReportStore.scope(c);assertEquals(0,ReportStore.load(c,two,day,"").getJSONArray("versions").length());DriveBackup.prefs(c).edit().clear().commit();assertEquals(1,ReportStore.load(c,scope,day,"").getJSONArray("versions").length());}
 @Test public void userConfirmedPeopleAreSeparateAndSameNamesDoNotAutoMerge()throws Exception {JSONObject a=ReportStore.person(c,scope,new JSONObject().put("name","같은 이름")),b=ReportStore.person(c,scope,new JSONObject().put("name","같은 이름"));assertNotEquals(a.getString("id"),b.getString("id"));JSONObject r=ReportStore.save(c,scope,day,report());ReportStore.review(c,scope,day,r.getString("id"),review(a.getString("id")));ReportStore.person(c,scope,new JSONObject().put("id",a.getString("id")).put("name","정정 이름"));JSONObject loaded=ReportStore.load(c,scope,day,"");assertEquals(2,loaded.getJSONArray("people").length());assertEquals("추정 이름",loaded.getJSONObject("report").getJSONArray("speakers").getJSONObject(0).getString("name"));ReportStore.deletePerson(c,scope,a.getString("id"));assertEquals(0,ReportStore.load(c,scope,day,"").getJSONObject("review").getJSONArray("links").length());}
 @Test public void invalidInputAndSampleNeverOverwriteReports()throws Exception {ReportStore.save(c,scope,day,report());for(String d:new String[]{"../2026-10-30","2026-02-30","2026-1-01"})try{ReportStore.save(c,scope,d,report());fail(d);}catch(Exception expected){}try{ReportStore.save(c,scope,day,report().put("sample",true));fail();}catch(java.io.IOException expected){}try{ReportStore.save(c,scope,day,report().put("todos",new JSONArray().put(new JSONObject().put("title","task").put("due","2026-02-30"))));fail();}catch(Exception expected){}assertEquals(1,ReportStore.load(c,scope,day,"").getJSONArray("versions").length());}
 @Test public void atomicRecoveryAndExplicitDeletionDoNotTouchAudioOrPeople()throws Exception {JSONObject r=ReportStore.save(c,scope,day,report());java.io.File f=new java.io.File(ReportStore.root(c,scope),day+"/"+r.getString("id")+".json");android.util.AtomicFile a=new android.util.AtomicFile(f);java.io.FileOutputStream out=a.startWrite();out.write("partial".getBytes());out.close();assertEquals(1,ReportStore.load(c,scope,day,"").getJSONArray("versions").length());assertTrue(f.renameTo(new java.io.File(f+".bak")));assertEquals(1,ReportStore.load(c,scope,day,"").getJSONArray("versions").length());ReportStore.person(c,scope,new JSONObject().put("name","사용자 확인"));java.io.File audio=new java.io.File(c.getFilesDir(),"audio-kept.m4a");audio.createNewFile();ReportStore.delete(c,scope,day);assertEquals(0,ReportStore.load(c,scope,day,"").getJSONArray("versions").length());assertEquals(1,ReportStore.load(c,scope,day,"").getJSONArray("people").length());assertTrue(audio.exists());}
}
